{
  "title": "configurable-ingestion-version-header",
  "request": "Hey, can we make the ingestion version header configurable on the LangfuseSpanProcessor? I'd like to pass an ingestion_version argument and have the x-langfuse-ingestion-version header reflect it (default should stay "4").",
  "edits": [
    {
      "path": "langfuse/_client/span_processor.py",
      "search": "        mask_otel_spans: Optional[MaskOtelSpansFunction] = None,",
      "replace": "        mask_otel_spans: Optional[MaskOtelSpansFunction] = None,
        ingestion_version: Optional[str] = None,"
    },
    {
      "path": "langfuse/_client/span_processor.py",
      "search": "# Prepare default headers
        default_headers = {
            "Authorization": basic_auth_header,
            "x-langfuse-sdk-name": "python",
            "x-langfuse-sdk-version": langfuse_version,
            "x-langfuse-public-key": public_key,
            "x-langfuse-ingestion-version": "4",
        }",
      "replace": "# Determine ingestion version (default "4")
        ingestion_version_val = ingestion_version if ingestion_version is not None else "4"

        # Prepare default headers
        default_headers = {
            "Authorization": basic_auth_header,
            "x-langfuse-sdk-name": "python",
            "x-langfuse-sdk-version": langfuse_version,
            "x-langfuse-public-key": public_key,
            "x-langfuse-ingestion-version": ingestion_version_val,
        }"
    }
  ],
  "test_path": "tests/unit/test_span_processor_ingestion_version.py",
  "test": "import pytest
from langfuse._client.span_processor import LangfuseSpanProcessor


def _get_exporter_headers(processor: LangfuseSpanProcessor) -> dict:
    exporter = getattr(processor, "_span_exporter", None)
    if exporter is None:
        return {}
    # OTLPSpanExporter stores headers in either 'headers' or a private '_headers' attribute.
    return getattr(exporter, "headers", getattr(exporter, "_headers", {}))


def test_ingestion_version_header_defaults():
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://example.com",
        span_exporter=None,
    )
    try:
        headers = _get_exporter_headers(processor)
        assert headers.get("x-langfuse-ingestion-version") == "4"
    finally:
        processor.shutdown()


def test_ingestion_version_header_custom():
    processor = LangfuseSpanProcessor(
        public_key="pk-test",
        secret_key="sk-test",
        base_url="http://example.com",
        ingestion_version="5",
        span_exporter=None,
    )
    try:
        headers = _get_exporter_headers(processor)
        assert headers.get("x-langfuse-ingestion-version") == "5"
    finally:
        processor.shutdown()
"
}
